insert into public.articles (id,title,slug,excerpt,content,cover,section_id,category_id,author,tags,status,published_at,created_at,updated_at) values ('art_2006','Hội đồng hương Hải Dương ra đời','hoi-dong-huong-hai-duong-ra-doi','Ngày 29/10/2006, Hội đồng hương Hải Dương được thành lập — tiền thân của Đội SVTN Đồng hương Hải Dương.','<p>Ngày 29/10/2006, anh Nguyễn Đức Dũng cùng những người bạn thành lập Hội đồng hương Hải Dương — tiền thân của Đội SVTN Đồng hương Hải Dương.</p><h2>Những ngày đầu khó khăn</h2><p>Giai đoạn 2006–2008, lực lượng và hoạt động còn hạn chế. Đội nhận được sự hỗ trợ nhiệt tình từ Đội SVTN Đồng hương Vĩnh Phúc và CLB Sinh viên tuyên truyền PCTNXH &amp; HIV/AIDS — cùng đi tập huấn, cùng tiếp sức mùa thi.</p><blockquote>Từ một nhóm sinh viên đồng hương, Đội đã trở thành nơi nhiều thế hệ gặp nhau, làm việc cùng nhau và trưởng thành cùng nhau.</blockquote>','img/hoi-dong-huong.webp','sec_gioithieu','cat_lichsu','Ban Truyền thông',array['2006','lịch sử']::text[],'published','2026-09-05T01:00:00.000Z','2026-09-04T08:00:00.000Z','2026-09-05T01:00:00.000Z') on conflict (id) do nothing;
insert into public.articles (id,title,slug,excerpt,content,cover,section_id,category_id,author,tags,status,published_at,created_at,updated_at) values ('art_2009','Mùa hè tình nguyện đầu tiên tại quê nhà','mua-he-tinh-nguyen-dau-tien-tai-que-nha','Năm 2009, 25 thành viên lên đường về xã Long Xuyên, huyện Kinh Môn — khởi đầu truyền thống Hè Xanh của Đội.','<p>Năm 2009, Đội được Đoàn trường cử tham gia chiến dịch tình nguyện tại Hải Dương với 25 thành viên tại xã Long Xuyên, huyện Kinh Môn, kèm một suất tài trợ xây nhà tình nghĩa trị giá 20 triệu đồng.</p><p>Từ điểm khởi đầu đó, Hè Xanh trở thành chiến dịch trọng tâm và là một trong những truyền thống bền bỉ nhất của Đội.</p><h2>Chính thức trực thuộc Hội Sinh viên</h2><p>Ngày 28.11.2009, sau ba năm hoạt động, Hội Sinh viên Trường ĐH Kinh tế Quốc dân công nhận Đội là đơn vị trực thuộc.</p>','img/mua-he-xanh.webp','sec_gioithieu','cat_lichsu','Ban Truyền thông',array['2009','hè xanh','lịch sử']::text[],'published','2026-09-06T01:00:00.000Z','2026-09-05T08:00:00.000Z','2026-09-12T03:20:00.000Z') on conflict (id) do nothing;
insert into public.articles (id,title,slug,excerpt,content,cover,section_id,category_id,author,tags,status,published_at,created_at,updated_at) values ('art_2010','Hành Trang Sĩ Tử và Tiếp Sức Mùa Thi đầu tiên','hanh-trang-si-tu-va-tiep-suc-mua-thi','Khởi nguồn từ K50, Hành Trang Sĩ Tử trở thành hoạt động thường niên mỗi tháng 3 của Đội.','<p>Khởi nguồn từ K50 và chính thức triển khai từ K51, Hành Trang Sĩ Tử trở thành hoạt động thường niên mỗi tháng 3 của Đội.</p><p>Tiếp sức mùa thi cũng là một phần không thể thiếu trong mỗi mùa hè tình nguyện. Dù nay đã không còn, đó vẫn là một chương trình lớn đáng nhớ.</p>','img/tiep-suc-mua-thi.webp','sec_gioithieu','cat_lichsu','Ban Truyền thông',array['2010','tiếp sức mùa thi']::text[],'archived','2026-09-07T01:00:00.000Z','2026-09-06T08:00:00.000Z','2026-10-01T02:00:00.000Z') on conflict (id) do nothing;
insert into public.articles (id,title,slug,excerpt,content,cover,section_id,category_id,author,tags,status,published_at,created_at,updated_at) values ('art_2014','Lễ hội Xuân Thành Đông','le-hoi-xuan-thanh-dong','Một trong những chương trình quy mô và ấn tượng nhất trong lịch sử Đội, kéo dài hơn một tháng.','<p>Năm 2014, Lễ hội Xuân Thành Đông trở thành một trong những chương trình quy mô và ấn tượng nhất trong lịch sử Đội.</p><p>Kéo dài hơn một tháng, lễ hội là chuỗi hoạt động sôi nổi:</p><ul><li>Cảnh sắc Thành Đông</li><li>Con đường màu xanh</li><li>Tết Sum Vầy</li><li>Không gian văn hóa truyền thống</li><li>Đêm nhạc Sắc Xuân</li></ul>','img/xuan-thanh-dong.webp','sec_gioithieu','cat_lichsu','Ban Truyền thông',array['2014','tết sum vầy']::text[],'published','2026-09-08T01:00:00.000Z','2026-09-07T08:00:00.000Z','2026-09-08T01:00:00.000Z') on conflict (id) do nothing;
insert into public.articles (id,title,slug,excerpt,content,cover,section_id,category_id,author,tags,status,published_at,created_at,updated_at) values ('art_2022','Tình nguyện vùng cao đầu tiên','tinh-nguyen-vung-cao-dau-tien','Trạm Tấu (Yên Bái) là điểm đến đầu tiên của chương trình Tình nguyện vùng cao năm 2022.','<p>Năm 2022, Trạm Tấu (Yên Bái) trở thành điểm đến đầu tiên của chương trình Tình nguyện vùng cao, đánh dấu bước chân của màu áo xanh Hải Dương đến với những miền đất ngoài quê hương.</p><p>Sau Trạm Tấu, chương trình tiếp tục được tổ chức tại Sơn La, Bắc Kạn, mang sức trẻ và những hoạt động sẻ chia đến với trẻ em, người dân địa phương.</p>','img/vung-cao.webp','sec_gioithieu','cat_lichsu','Ban Truyền thông',array['2022','vùng cao']::text[],'draft',null,'2026-10-02T08:00:00.000Z','2026-10-09T14:30:00.000Z') on conflict (id) do nothing;
insert into public.articles (id,title,slug,excerpt,content,cover,section_id,category_id,author,tags,status,published_at,created_at,updated_at) values ('art_ynghia','Một tiếng gọi thân quen, một cuộc trở về','mot-tieng-goi-than-quen-mot-cuoc-tro-ve','Khi Đội tròn 20 tuổi, có một điều vẫn còn nguyên: mong muốn được gặp lại nhau.','<p>Ngày ấy, rời gia đình lên Hà Nội với nhiều bỡ ngỡ, chúng mình gặp nhau ở Đội. Một tiếng chào đồng hương, rồi thành bạn, thành đồng đội, thành những người ở bên nhau trong những tháng ngày đẹp đẽ và chông chênh nhất của tuổi trẻ.</p><p>Rồi mỗi người lớn lên và đi về một hướng. Nhưng khi Đội tròn 20 tuổi, có một điều vẫn còn nguyên: mong muốn được gặp lại nhau, kể tiếp những câu chuyện cũ và cảm ơn những người đã cùng vun đắp mái nhà này.</p><h2>01 · Tiếng gọi</h2><p>Tiếng gọi đã quen từ những năm tháng cùng khoác áo xanh, cùng đi qua những chuyến đi và cùng tạo nên thanh xuân của nhau.</p><h2>02 · Lời hẹn</h2><p>Có những nơi dù rời xa bao lâu vẫn luôn có cảm giác thuộc về. 20 năm là dịp để chúng mình trở lại bên nhau, gặp lại những gương mặt thân quen và nối tiếp câu chuyện giữa các thế hệ.</p>','img/thap-nen.webp','sec_gioithieu','cat_ynghia','Ban Truyền thông',array['20 năm','anh em ơi']::text[],'published','2026-09-10T01:00:00.000Z','2026-09-09T08:00:00.000Z','2026-09-10T01:00:00.000Z') on conflict (id) do nothing;
insert into public.articles (id,title,slug,excerpt,content,cover,section_id,category_id,author,tags,status,published_at,created_at,updated_at) values ('art_trienlam','Triển lãm đa giác quan “Bảo tàng ký ức”','trien-lam-bao-tang-ky-uc','Con đường kỷ niệm kể câu chuyện “20 năm chung một mái nhà” qua hình ảnh, âm thanh, kỷ vật và tư liệu của 20 thế hệ.','<p><strong>24.10 · 9h – 17h</strong></p><p>Con đường kỷ niệm kể câu chuyện “20 năm chung một mái nhà” qua hình ảnh, âm thanh, kỷ vật và tư liệu của 20 thế hệ.</p><p>Mỗi người đều có thể tìm thấy một phần thanh xuân của mình ở đây — và để lại lá thư gửi chính mình.</p>','img/trien-lam.webp','sec_lichtrinh','cat_ngayhoi','Ban Sự kiện',array['24.10','triển lãm']::text[],'published','2026-10-01T01:00:00.000Z','2026-09-28T08:00:00.000Z','2026-10-03T07:45:00.000Z') on conflict (id) do nothing;
insert into public.articles (id,title,slug,excerpt,content,cover,section_id,category_id,author,tags,status,published_at,created_at,updated_at) values ('art_tracda','Quán trà đá & du ca','quan-tra-da-du-ca','Khoảng hẹn thân quen bên cốc trà đá và tiếng guitar.','<p><strong>24.10 · 9h – 17h</strong></p><p>Khoảng hẹn thân quen bên cốc trà đá và tiếng guitar. Ngồi xuống, ôn lại kỷ niệm và cùng hát những bài ca quen thuộc của Đội:</p><ol><li>Bài ca sinh viên</li><li>Mùa hè xanh</li><li>Hải Dương xanh</li></ol>','img/tra-da-du-ca.webp','sec_lichtrinh','cat_ngayhoi','Ban Sự kiện',array['24.10','du ca']::text[],'draft',null,'2026-10-04T08:00:00.000Z','2026-10-10T10:05:00.000Z') on conflict (id) do nothing;
insert into public.articles (id,title,slug,excerpt,content,cover,section_id,category_id,author,tags,status,published_at,created_at,updated_at) values ('art_luatrai','Đêm giao lưu lửa trại','dem-giao-luu-lua-trai','Ngọn lửa của những mùa hè tình nguyện được thắp lại. Hát cùng nhau, thức cùng nhau tới khi trời sáng.','<p><strong>24.10 · 21h – 6h sáng</strong></p><p>Ngọn lửa của những mùa hè tình nguyện được thắp lại. Hát cùng nhau, nhảy cùng nhau, thức cùng nhau tới khi trời sáng.</p>','img/lua-trai.webp','sec_lichtrinh','cat_ngayhoi','Ban Sự kiện',array['24.10','lửa trại']::text[],'published','2026-10-02T01:00:00.000Z','2026-09-29T08:00:00.000Z','2026-10-02T01:00:00.000Z') on conflict (id) do nothing;
insert into public.articles (id,title,slug,excerpt,content,cover,section_id,category_id,author,tags,status,published_at,created_at,updated_at) values ('art_thethao','Lịch thi đấu chuỗi giải thể thao','lich-thi-dau-chuoi-giai-the-thao','Pickleball, Cầu lông, Bóng đá, Esport — ra sân cùng nhau như những ngày còn ở Đội.','<h2>Pickleball</h2><p>Đôi nam · Đôi nam nữ</p><ul><li>Sáng CN 11.10: khai mạc, vòng bảng</li><li>Sáng T7 24.10: bán kết, chung kết, tranh hạng 3</li></ul><h2>Cầu lông</h2><p>Đôi nam · Đôi nam nữ</p><ul><li>Sáng CN 11.10: khai mạc, vòng bảng</li><li>Sáng T7 24.10: bán kết, chung kết, tranh hạng 3</li></ul><h2>Bóng đá</h2><p>6 đội · 2 bảng · vòng tròn 1 lượt</p><ul><li>Sáng CN 18.10: khai mạc, vòng bảng</li><li>Chiều T7 24.10: bán kết, chung kết, tranh hạng 3</li></ul><h2>Esport</h2><p>Liên Minh Huyền Thoại · Liên Quân Mobile · Bo3</p><ul><li>26 – 27.09 (online): khai mạc, vòng bảng, bán kết</li><li>04.10 (LMHT) · 05.10 (LQ): chung kết &amp; tranh hạng 3, offline</li></ul>','','sec_lichtrinh','cat_thethao','Ban Thể thao',array['thể thao','lịch thi đấu']::text[],'published','2026-09-20T01:00:00.000Z','2026-09-18T08:00:00.000Z','2026-10-05T09:40:00.000Z') on conflict (id) do nothing;
insert into public.articles (id,title,slug,excerpt,content,cover,section_id,category_id,author,tags,status,published_at,created_at,updated_at) values ('art_loinhan','Lời nhắn gửi về nhà','loi-nhan-gui-ve-nha','Những lời nhắn đầu tiên từ các thế hệ thành viên gửi về mái nhà HDX.','<blockquote>Gặp lại anh em, mình vẫn thấy như được về nhà. Mình tự hào về Đội và thêm tin tưởng các em hôm nay. — Một cựu thành viên</blockquote><blockquote>Mình hiểu vì sao các anh chị gọi Đội là nhà. Mình tự hào được góp phần vào 20 năm ấy và muốn gìn giữ sự gắn bó này. — Một thành viên hiện tại</blockquote><blockquote>Mình được đón nhận vào một mái nhà có nhiều câu chuyện đẹp, và từ hôm nay sẽ có thêm ký ức của mình. — Một thành viên mới</blockquote><p>Bạn muốn gửi lời nhắn? Hãy bắt đầu từ một câu: “Nếu về tham dự sinh nhật Đội, tôi muốn được gặp lại… vì…”</p>','img/loi-hen.webp','sec_baotang','cat_loihen','Ban Truyền thông',array['lời hẹn ước']::text[],'draft',null,'2026-10-06T08:00:00.000Z','2026-10-11T02:30:00.000Z') on conflict (id) do nothing;
